using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Text; using CompanyManagement.Api.DTOs; using Microsoft.AspNetCore.Identity; using Microsoft.IdentityModel.Tokens;
namespace CompanyManagement.Api.Services;
public interface IAuthService { Task<(bool ok,string? error)> Register(RegisterDto dto); Task<(string? token,DateTime? expires,string? error)> Login(LoginDto dto); }
public class AuthService(UserManager<IdentityUser> users,IConfiguration config):IAuthService { public async Task<(bool,string?)> Register(RegisterDto d){if(await users.FindByEmailAsync(d.Email)!=null)return(false,"El email ya está registrado.");var u=new IdentityUser{UserName=d.Email,Email=d.Email,EmailConfirmed=true};var r=await users.CreateAsync(u,d.Password);if(!r.Succeeded)return(false,string.Join(" ",r.Errors.Select(x=>x.Description)));await users.AddToRoleAsync(u,"User");return(true,null);} public async Task<(string?,DateTime?,string?)> Login(LoginDto d){var u=await users.FindByEmailAsync(d.Email);if(u==null||!await users.CheckPasswordAsync(u,d.Password))return(null,null,"Credenciales inválidas.");var key=config["Jwt:Key"]??throw new InvalidOperationException("JWT Key no configurada");var exp=DateTime.UtcNow.AddMinutes(int.TryParse(config["Jwt:ExpirationMinutes"],out var m)?m:120);var claims=new List<Claim>{new(JwtRegisteredClaimNames.Sub,u.Id),new(JwtRegisteredClaimNames.Email,u.Email??"")};claims.AddRange((await users.GetRolesAsync(u)).Select(x=>new Claim(ClaimTypes.Role,x)));var token=new JwtSecurityToken(issuer:config["Jwt:Issuer"],audience:config["Jwt:Audience"],claims:claims,expires:exp,signingCredentials:new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),SecurityAlgorithms.HmacSha256));return(new JwtSecurityTokenHandler().WriteToken(token),exp,null);} }
